effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    vec2 center = vec2(0.5 + 0.25 * uControl3,
                       0.5 + 0.25 * uControl4);
    vec2 delta = uv - center;
    float distanceToCenter = max(length(delta), 0.00001);
    float strength = clamp(0.12 + 0.08 * uControl2, 0.0, 0.4);
    vec2 span = delta * strength;
    if (uControl5 > 0.5) {
        span = delta / distanceToCenter * strength * 0.25;
    }
    vec4 sum = vec4(0.0);
    for (int i = 0; i < 13; ++i) {
        float t = float(i) / 12.0;
        vec2 p = clamp(uv - span * t, 0.0, 1.0);
        sum += fxPortSample(inputImg.texture, p);
    }
    vec4 effected = sum / 13.0;
    fxPortOutput = clamp(mix(original, effected,
                             clamp(uControl1, 0.0, 1.0)), 0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
